62	/**
63	 * Moves the claim to its new status: DRAFT to OPEN, OPEN to SETTLED (or PENDING), PENDING to SETTLED (approve) or back
64	 * to OPEN (reject), DRAFT, OPEN or PENDING to VOID. A voided claim keeps
65	 * its number (never given again). Settling fixes the claim's due: its amount at its
66	 * person's grade's rate in force on the claim's date, rounded by its rounding (see Rounding) and at least the sheet's floor (left live when no rate applies),
67	 * or the figure a statement bound it to, with its late charge as of the sheet's today frozen in (see LateCharge).
68	 * Opening records who opened the claim; that user cannot settle nor approve it (four eyes). A claim dated inside a closed
69	 * period cannot change status, nor can a deferred claim be settled (see ClaimDue#deferred). A clerk (any user not made a steward) settling a claim whose due is above the sheet's
70	 * clerk limit, if it has one, makes it PENDING instead (its due left live, not bound by a statement); a due of n/a is
71	 * within any limit. A steward settles anything. Only a steward approves a PENDING claim (fixing its live figure, late
72	 * charge included, at that moment) or rejects it (OPEN again, bound again by its statement if one bound it).
73	 * Only a steward re-settles a SETTLED claim (not one dated inside a closed period): its due is fixed again at the figure
74	 * it would have today as an OPEN claim bound by no statement (today's rates, grades, floor and late charge).
75	 */
76	public class ApplyClaimStatus {
77	    public void apply(@Val Claim claim, @Val ClaimStatusChange change, PersonRepository people, RateRepository rates,
78	            PeriodRepository periods, SettingRepository settings, RoleRepository roles, SheetRepository sheets, ClaimRepository claims, Out<Claim> changed, Out<ClaimNumber> number, Out<PreviousDue> previous) throws InvalidClaimStatusException {
79	        boolean allowed = switch (change.action()) {
80	            case OPEN -> claim.status() == ClaimStatus.DRAFT;
81	            case SETTLE -> claim.status() == ClaimStatus.OPEN;
82	            case APPROVE, REJECT -> claim.status() == ClaimStatus.PENDING;
83	            case VOID -> claim.status() == ClaimStatus.DRAFT || claim.status() == ClaimStatus.OPEN
84	                    || claim.status() == ClaimStatus.PENDING;
85	            case RESETTLE -> claim.status() == ClaimStatus.SETTLED;
86	        };
87	        if (!allowed) {
88	            throw new InvalidClaimStatusException("A " + claim.status() + " claim cannot be made " + change.to());
89	        }
90	        if (periods.closedOn(claim.sheetId(), claim.date())) {
91	            throw new InvalidClaimStatusException("The claim's date is inside a closed period");
92	        }
93	        if (change.action() == ClaimAction.SETTLE && ClaimDue.deferred(claim, sheets.today(claim.sheetId()))) {
94	            throw new InvalidClaimStatusException("A deferred claim cannot be settled until the date it is deferred until");
95	        }
96	        boolean steward = RoleRepository.STEWARD.equals(roles.roleOf(claim.sheetId(), change.by()));
97	        if ((change.action() == ClaimAction.SETTLE || change.action() == ClaimAction.APPROVE)
98	                && change.by().equals(claim.openedBy())) {
99	            throw new InvalidClaimStatusException("The user who opened a claim cannot settle nor approve it");
100	        }
101	        if ((change.action() == ClaimAction.APPROVE || change.action() == ClaimAction.REJECT) && !steward) {
102	            throw new InvalidClaimStatusException("Only a steward approves or rejects a pending claim");
103	        }
104	        if (change.action() == ClaimAction.RESETTLE && !steward) {
105	            throw new InvalidClaimStatusException("Only a steward re-settles a claim");
106	        }
107	        ClaimStatus to = change.to();
108	        LateCharge late = LateCharge.of(claim.sheetId(), sheets, settings, claims);
109	        BigDecimal settledDue;
110	        if (change.action() == ClaimAction.RESETTLE) {
111	            Claim asOpen = new Claim(claim.id(), claim.sheetId(), claim.personId(), claim.amount(), claim.date(),
112	                    claim.note(), ClaimStatus.OPEN, claim.number(), null, claim.openedBy(), false, null,
113	                    claim.corrects(), claim.dueBy(), null);
114	            settledDue = late.add(asOpen, due(asOpen, people, rates, settings, late.rounding()));
115	        } else {
116	            settledDue = to == ClaimStatus.SETTLED ? late.add(claim, due(claim, people, rates, settings, late.rounding())) : claim.due();
117	        }
118	        if (change.action() == ClaimAction.SETTLE && settledDue != null && !steward) {
119	            BigDecimal limit = settings.clerkLimit(claim.sheetId());
120	            if (limit != null && settledDue.compareTo(limit) > 0) {
121	                to = ClaimStatus.PENDING;
122	                settledDue = null;
123	            }
124	        }
125	        number.set(new ClaimNumber(claim.number()));
126	        previous.set(new PreviousDue(claim.due()));
127	        changed.set(new Claim(claim.id(), claim.sheetId(), claim.personId(), claim.amount(), claim.date(),
128	                claim.note(), to, claim.number(), settledDue,
129	                change.action() == ClaimAction.OPEN ? change.by() : claim.openedBy(), claim.stated(), claim.statedDue(), claim.corrects(), claim.dueBy(), claim.deferredUntil()));
130	    }
131	    private static BigDecimal due(Claim claim, PersonRepository people, RateRepository rates, SettingRepository settings,
132	            Rounding rounding) {
133	        if (claim.stated() && claim.status() != ClaimStatus.PENDING) {
134	            return claim.statedDue();
135	        }
136	        Person person = people.find(claim.sheetId(), claim.personId());
137	        return person == null ? null : ClaimDue.live(claim, person.gradeOn(claim.date()), rates, settings.floor(claim.sheetId(), claim.date()), rounding);
138	    }
139	}
