169	public class ApplyReassign {
170	    public void apply(@Val Claim claim, @Val ReassignRequest request, PersonRepository people, RoleRepository roles,
171	            PeriodRepository periods, Out<ClaimReassignment> reassignment) throws InvalidClaimStatusException {
172	        if (!RoleRepository.STEWARD.equals(roles.roleOf(claim.sheetId(), request.by()))) {
173	            throw new InvalidClaimStatusException("Only a steward moves a claim");
174	        }
175	        if (claim.status() != ClaimStatus.DRAFT && claim.status() != ClaimStatus.OPEN
176	                && claim.status() != ClaimStatus.PENDING) {
177	            throw new InvalidClaimStatusException("A " + claim.status() + " claim cannot move");
178	        }
179	        if (claim.corrects() != null) {
