181	        }
182	        if (periods.closedOn(claim.sheetId(), claim.date())) {
183	            throw new InvalidClaimStatusException("The claim's date is inside a closed period");
184	        }
185	        Person from = people.find(claim.sheetId(), claim.personId());
186	        Person to = people.find(claim.sheetId(), request.personId());
