242	/** The figures a claim has: live, fixed when settled, or bound by a statement. */
243	public final class ClaimDue {
244	    private ClaimDue() {
245	    }
246	    /** Whether a claim counts toward claimed and the totals: only OPEN, PENDING and SETTLED claims do. */
247	    public static boolean counts(Claim claim) {
248	        return isOpen(claim) || claim.status() == ClaimStatus.SETTLED;
249	    }
250	    /** Whether a claim is open: OPEN, or PENDING (handled like an OPEN claim but for its statement binding). */
251	    public static boolean isOpen(Claim claim) {
252	        return claim.status() == ClaimStatus.OPEN || claim.status() == ClaimStatus.PENDING;
253	    }
254	    /** Whether a claim counts toward the live totals (claimed, due-totals, a period's due-total): one that counts,
255	     *  unless it is open (OPEN or PENDING), not bound by a statement, and dated within a hold of its person (null: none). */
256	    public static boolean countsLive(Claim claim, net.officefloor.hq.app.person.Person person) {
257	        return counts(claim) && !(isOpen(claim) && !bound(claim) && person != null && person.heldOn(claim.date()));
258	    }
259	    /** Whether a claim is deferred on the given today: an OPEN claim deferred until a date after it. Until then it
260	     *  counts in no total, is not overdue, cannot be settled and is left unbound by a statement; from that day on
261	     *  it is an OPEN claim like any other. */
262	    public static boolean deferred(Claim claim, java.time.LocalDate today) {
263	        return claim.status() == ClaimStatus.OPEN && claim.deferredUntil() != null
264	                && claim.deferredUntil().isAfter(today);
265	    }
266	    /** Whether a claim counts toward the live totals on the given today: as {@link #countsLive(Claim,
267	     *  net.officefloor.hq.app.person.Person)}, unless it is deferred. */
268	    public static boolean countsLive(Claim claim, net.officefloor.hq.app.person.Person person,
269	            java.time.LocalDate today) {
270	        return countsLive(claim, person) && !deferred(claim, today);
271	    }
272	    /** The claim's amount at the grade's rate in force on its date, rounded to two decimals by the claim's rounding
273	     *  (see Rounding), and at least the sheet's floor (a correction has no floor); null when no rate applies. */
274	    public static BigDecimal live(Claim claim, String grade, RateRepository rates, BigDecimal floor, Rounding rounding) {
275	        Rate rate = rates.find(claim.sheetId(), grade, claim.date());
276	        if (rate == null) {
277	            return null;
278	        }
279	        BigDecimal due = claim.amount().multiply(rate.rate()).movePointLeft(2).setScale(2, rounding.mode(claim));
280	        return isCorrection(claim) ? due : due.max(floor);
281	    }
282	    /** Whether the claim is a correction: its amount is negative. */
283	    public static boolean isCorrection(Claim claim) {
