733	/**
734	 * The late charge on a sheet as of its today: an overdue claim (OPEN or PENDING, its due-by — fixed when it was added — before
735	 * today) gains the late percent in force on its date of its figure for every full 30 days it is overdue, rounded to two
736	 * decimals by the claim's rounding (see Rounding). The charge is never bound by a statement (it follows today); settling freezes it into the claim's due.
737	 */
738	public record LateCharge(LocalDate today, Function<LocalDate, BigDecimal> pct, Rounding rounding) {
739	    /** The days in each step of the charge. */
740	    public static final int DAYS = 30;
741	    public static LateCharge of(String sheetId, SheetRepository sheets, SettingRepository settings,
742	            ClaimRepository claims) {
743	        return new LateCharge(sheets.today(sheetId), (date) -> settings.latePct(sheetId, date),
744	                Rounding.of(sheetId, sheets, settings, claims));
745	    }
746	    /** The charge on the claim with the given figure: zero when it is not overdue a full 30 days, has no figure, is
747	     *  a correction, or is deferred. */
748	    public BigDecimal on(Claim claim, BigDecimal figure) {
749	        if (figure == null || !ClaimDue.isOpen(claim) || claim.due() != null || ClaimDue.isCorrection(claim)
750	                || ClaimDue.deferred(claim, today)) {
751	            return BigDecimal.ZERO.setScale(2);
752	        }
753	        long overdue = ChronoUnit.DAYS.between(claim.dueBy(), today);
754	        long steps = overdue <= 0 ? 0 : overdue / DAYS;
755	        return figure.multiply(pct.apply(claim.date())).multiply(BigDecimal.valueOf(steps)).movePointLeft(2)
756	                .setScale(2, rounding.mode(claim));
757	    }
758	    /** The figure with its charge added on top; null when it has none. */
759	    public BigDecimal add(Claim claim, BigDecimal figure) {
760	        return figure == null ? null : figure.add(on(claim, figure));
761	    }
762	}
