781	/**
782	 * Opens each selected claim that can be opened, in list order (people in the order they were added, a person's
783	 * claims newest first): as the single open does, it must be a DRAFT not dated inside a closed period, takes its
784	 * number (see ClaimNumbering) and records who opened it, adds its OPEN line to its status log (see ClaimLog), then writes CLAIM_OPENED and the figures it moved (see Rollup).
785	 * Each that cannot, or is not on the sheet, is left as it is and counted refused.
786	 */
787	public class OpenClaims {
788	    public void open(@PathVariable("sheetId") String sheetId, @Val BulkOpenRequest request, ClaimRepository claims,
789	            PersonRepository people, PeriodRepository periods, SettingRepository settings, SheetRepository sheets, Rollup rollup, Audit audit, ClaimLog log,
790	            Out<BulkOpenResult> result) {
791	        String sheet = sheetId.trim();
792	        Set<Long> selected = new HashSet<>(request.claimIds());
793	        List<Person> listed = people.list(sheet);
794	        Map<Long, Integer> personOrder = new HashMap<>();
795	        for (int i = 0; i < listed.size(); i++) {
796	            personOrder.put(listed.get(i).id(), i);
797	        }
798	        Map<Long, Person> byId = listed.stream().collect(Collectors.toMap(Person::id, (p) -> p));
799	        List<Claim> chosen = claims.list(sheet).stream().filter((c) -> selected.contains(c.id()))
800	                .sorted((a, b) -> Integer.compare(personOrder.getOrDefault(a.personId(), Integer.MAX_VALUE),
801	                        personOrder.getOrDefault(b.personId(), Integer.MAX_VALUE)))
802	                .toList();
803	        int opened = 0;
804	        for (Claim claim : chosen) {
805	            if (claim.status() != ClaimStatus.DRAFT || periods.closedOn(sheet, claim.date())) {
806	                continue;
807	            }
808	            RollupBefore before = rollup.take(sheet);
809	            String number = ClaimNumbering.next(claim, claims, periods, settings, sheets);
810	            Claim toSave = new Claim(claim.id(), claim.sheetId(), claim.personId(), claim.amount(), claim.date(),
811	                    claim.note(), ClaimStatus.OPEN, number, claim.due(), request.by(), claim.stated(),
812	                    claim.statedDue(), claim.corrects(), claim.dueBy(), claim.deferredUntil());
813	            if (!claims.updateStatus(toSave, ClaimStatus.DRAFT)) {
814	                continue;
815	            }
816	            opened++;
817	            log.write(toSave, request.by());
818	            Person person = byId.get(claim.personId());
819	            audit.record("CLAIM_OPENED sheet=" + sheet + " by=" + request.by() + " person="
820	                    + (person == null ? "" : person.name()) + " amount=" + claim.amount().toPlainString()
821	                    + " date=" + claim.date() + " number=" + number);
822	            rollup.record(sheet, request.by(), before);
823	        }
824	        result.set(new BulkOpenResult(opened, selected.size() - opened));
825	    }
826	}
