987	/**
988	 * How a claim's live figures (the rate step and the late charge) are rounded to two decimals: a claim dated before
989	 * the sheet's policy date (its today while the policy date is blank) rounds half up, one dated on or after it half to
990	 * even. A correction rounds by the date of the claim it corrects, not its own.
991	 */
992	public record Rounding(LocalDate policy, ClaimRepository claims) {
993	    public static Rounding of(String sheetId, SheetRepository sheets, SettingRepository settings, ClaimRepository claims) {
994	        LocalDate policy = settings.policyDate(sheetId);
995	        return new Rounding(policy == null ? sheets.today(sheetId) : policy, claims);
996	    }
997	    /** The date that decides how the claim rounds: the corrected claim's date for a correction, else its own. */
998	    public static LocalDate roundsOn(Claim claim, ClaimRepository claims) {
999	        if (claim.corrects() != null) {
1000	            Claim corrected = claims.findByNumber(claim.sheetId(), claim.personId(), claim.corrects());
1001	            if (corrected != null) {
1002	                return corrected.date();
1003	            }
1004	        }
1005	        return claim.date();
1006	    }
1007	    /** The rounding the claim's live figures take. */
1008	    public RoundingMode mode(Claim claim) {
1009	        return roundsOn(claim, claims).isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
1010	    }
