1080	/**
1081	 * Settles each selected claim, in list order (people in the order they were added, a person's claims newest first),
1082	 * through the very steps of the single settle: ApplyClaimStatus (its rules, a clerk's settle above the clerk limit
1083	 * making it PENDING), SaveClaimStatus (its status log line) and RecordClaimStatusChanged (CLAIM_SETTLED or
1084	 * CLAIM_PENDING and the figures it moved). A claim made PENDING counts as settled. Each that the single settle would
1085	 * refuse, or is not on the sheet, is left as it is and counted refused.
1086	 */
1087	public class SettleClaims {
1088	    public void settle(@PathVariable("sheetId") String sheetId, @Val BulkSettleRequest request, ClaimRepository claims,
1089	            PersonRepository people, RateRepository rates, PeriodRepository periods, SettingRepository settings,
1090	            RoleRepository roles, SheetRepository sheets, Rollup rollup, Audit audit, ClaimLog log,
1091	            Out<BulkSettleResult> result) {
1092	        String sheet = sheetId.trim();
1093	        Set<Long> selected = new HashSet<>(request.claimIds());
1094	        List<Person> listed = people.list(sheet);
1095	        Map<Long, Integer> personOrder = new HashMap<>();
1096	        for (int i = 0; i < listed.size(); i++) {
1097	            personOrder.put(listed.get(i).id(), i);
1098	        }
1099	        List<Claim> chosen = claims.list(sheet).stream().filter((c) -> selected.contains(c.id()))
1100	                .sorted((a, b) -> Integer.compare(personOrder.getOrDefault(a.personId(), Integer.MAX_VALUE),
1101	                        personOrder.getOrDefault(b.personId(), Integer.MAX_VALUE)))
1102	                .toList();
1103	        ClaimStatusChange change = new ClaimStatusChange(ClaimAction.SETTLE, ClaimStatus.SETTLED, request.by(), "");
1104	        ApplyClaimStatus apply = new ApplyClaimStatus();
1105	        SaveClaimStatus save = new SaveClaimStatus();
1106	        RecordClaimStatusChanged record = new RecordClaimStatusChanged();
1107	        int settled = 0;
1108	        for (Claim listedClaim : chosen) {
1109	            Claim claim = claims.find(sheet, listedClaim.id());
1110	            if (claim == null) {
1111	                continue;
1112	            }
1113	            RollupBefore before = rollup.take(sheet);
1114	            Claim[] changed = new Claim[1];
1115	            Claim[] stored = new Claim[1];
1116	            ClaimNumber[] number = new ClaimNumber[1];
1117	            PreviousDue[] previous = new PreviousDue[1];
1118	            try {
1119	                apply.apply(claim, change, people, rates, periods, settings, roles, sheets, claims,
1120	                        (c) -> changed[0] = c, (n) -> number[0] = n, (p) -> previous[0] = p);
1121	                save.save(changed[0], change, claims, periods, settings, sheets, log, (c) -> stored[0] = c,
1122	                        (n) -> number[0] = n);
1123	            } catch (InvalidClaimStatusException refused) {
1124	                continue;
1125	            }
1126	            settled++;
1127	            record.record(stored[0], change, number[0], previous[0], people, before, rollup, audit);
1128	        }
1129	        result.set(new BulkSettleResult(settled, selected.size() - settled));
1130	    }
1131	}
