11	/**
12	 * The sheet's figures as the screen shows them: each person's claimed (their claims that count added up; a person's OPEN or PENDING claims dated within a hold of theirs, not bound by a statement, do not, nor do deferred claims) and
13	 * due-total (the figures of those claims, each with its late charge, added up; n/a when their grade has no rate today and no counting claim
14	 * has a figure, kept or at the grade in force on its date; at most the sheet's cap), overdue-total (the figures, late charge included, of those claims that are overdue — open, their due-by before
15	 * today — added up, skipping n/a; not capped), and the sheet's claimed-total, due-total and overdue-total (everyone's added up, skipping n/a).
16	 *
17	 * A change takes the figures before it ({@link #take}) and, after its own audit lines, writes ROLLUP for every
18	 * person whose figures (claimed, due-total or overdue-total) moved (a person new to the sheet counts as moved), then
19	 * TOTALS when any of the sheet's three totals moved ({@link #record}).
20	 */
21	@Service
22	public class Rollup {
23	    private final PersonRepository people;
24	    private final ClaimRepository claims;
25	    private final RateRepository rates;
26	    private final SheetRepository sheets;
27	    private final SettingRepository settings;
28	    private final Audit audit;
29	    public Rollup(PersonRepository people, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
30	            SettingRepository settings, Audit audit) {
31	        this.people = people;
32	        this.claims = claims;
33	        this.rates = rates;
34	        this.sheets = sheets;
35	        this.settings = settings;
36	        this.audit = audit;
37	    }
38	    /** Every person's figures on the sheet now, in the order they were added. */
39	    public RollupBefore take(String sheetId) {
40	        LocalDate today = sheets.today(sheetId);
41	        BigDecimal cap = settings.cap(sheetId);
42	        LateCharge late = LateCharge.of(sheetId, sheets, settings, claims);
43	        List<Claim> all = claims.list(sheetId);
44	        Map<Long, Figures> figures = new LinkedHashMap<>();
45	        for (Person person : people.list(sheetId)) {
46	            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
47	            BigDecimal due = BigDecimal.ZERO.setScale(2);
48	            BigDecimal overdue = BigDecimal.ZERO.setScale(2);
49	            boolean figured = false;
50	            for (Claim c : all) {
51	                if (c.personId() != person.id() || !ClaimDue.countsLive(c, person, today)) {
52	                    continue;
53	                }
54	                claimed = claimed.add(c.amount());
55	                BigDecimal figure = late.add(c, ClaimDue.figure(c, person.gradeOn(c.date()), rates, settings.floor(sheetId, c.date()), late.rounding()));
56	                figured |= figure != null;
57	                if (figure != null) {
58	                    due = due.add(figure);
59	                    if (ClaimDue.isOpen(c) && c.dueBy().isBefore(today)) {
60	                        overdue = overdue.add(figure);
61	                    }
62	                }
63	            }
64	            String dueTotal = rates.find(sheetId, person.gradeOn(today), today) == null && !figured ? "n/a"
65	                    : SettingRepository.capped(due, cap).toPlainString();
66	            figures.put(person.id(), new Figures(person.name(), claimed.toPlainString(), dueTotal,
67	                    overdue.toPlainString()));
68	        }
69	        return new RollupBefore(figures);
70	    }
71	    /** Writes the ROLLUP and TOTALS lines for the figures the change moved since {@code before}. */
72	    public void record(String sheetId, String by, RollupBefore before) {
73	        Map<Long, Figures> after = take(sheetId).figures();
74	        for (Map.Entry<Long, Figures> e : after.entrySet()) {
75	            Figures was = before.figures().get(e.getKey());
76	            Figures now = e.getValue();
77	            if (was == null || !was.claimed().equals(now.claimed()) || !was.dueTotal().equals(now.dueTotal())
78	                    || !was.overdueTotal().equals(now.overdueTotal())) {
79	                audit.record("ROLLUP sheet=" + sheetId + " by=" + by + " person=" + now.name() + " claimed="
80	                        + now.claimed() + " due-total=" + now.dueTotal() + " overdue-total=" + now.overdueTotal());
81	            }
82	        }
83	        String claimedBefore = claimedTotal(before.figures());
84	        String dueBefore = dueTotal(before.figures());
85	        String claimedAfter = claimedTotal(after);
86	        String dueAfter = dueTotal(after);
87	        String overdueBefore = overdueTotal(before.figures());
88	        String overdueAfter = overdueTotal(after);
89	        if (!Objects.equals(claimedBefore, claimedAfter) || !Objects.equals(dueBefore, dueAfter)
90	                || !Objects.equals(overdueBefore, overdueAfter)) {
91	            audit.record("TOTALS sheet=" + sheetId + " by=" + by + " claimed-total=" + claimedAfter + " due-total="
92	                    + dueAfter + " overdue-total=" + overdueAfter);
93	        }
94	    }
95	    private static String claimedTotal(Map<Long, Figures> figures) {
96	        return figures.values().stream().map((f) -> new BigDecimal(f.claimed()))
97	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add).toPlainString();
98	    }
99	    private static String overdueTotal(Map<Long, Figures> figures) {
100	        return figures.values().stream().map((f) -> new BigDecimal(f.overdueTotal()))
101	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add).toPlainString();
102	    }
103	    private static String dueTotal(Map<Long, Figures> figures) {
104	        return figures.values().stream().filter((f) -> !f.dueTotal().equals("n/a"))
105	                .map((f) -> new BigDecimal(f.dueTotal())).reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add)
106	                .toPlainString();
107	    }
108	}
