623	 *  in it, each with its late charge, added up (skipping n/a). Each person's own due-total for the period is fixed
624	 *  too, for every person on the sheet; the period's is the sum of theirs. Closing a period already closed is refused. */
625	public class ClosePeriod {
626	    public void close(@Val Period period, @Val PeriodCloseRequest request, PeriodRepository periods,
627	            ClaimRepository claims, PersonRepository people, RateRepository rates, SettingRepository settings,
628	            SheetRepository sheets,
629	            Out<PeriodClose> closed)
630	            throws InvalidPeriodException {
631	        if (period.closed()) {
632	            throw new InvalidPeriodException("The period " + period.name() + " is already closed");
633	        }
634	        Map<Long, Person> byId = people.list(period.sheetId()).stream()
635	                .collect(Collectors.toMap(Person::id, (p) -> p));
636	        LateCharge late = LateCharge.of(period.sheetId(), sheets, settings, claims);
637	        Map<Long, BigDecimal> perPerson = new LinkedHashMap<>();
638	        for (Long id : byId.keySet()) {
639	            perPerson.put(id, BigDecimal.ZERO.setScale(2));
640	        }
641	        for (Claim c : claims.list(period.sheetId())) {
642	            Person person = byId.get(c.personId());
643	            if (!ClaimDue.countsLive(c, person, late.today()) || c.date().isBefore(period.from()) || c.date().isAfter(period.to())) {
644	                continue;
645	            }
646	            BigDecimal figure = person == null ? c.due() : late.add(c, ClaimDue.figure(c, person.gradeOn(c.date()), rates, settings.floor(c.sheetId(), c.date()), late.rounding()));
647	            if (figure != null) {
648	                perPerson.merge(c.personId(), figure, BigDecimal::add);
649	            }
650	        }
651	        BigDecimal total = perPerson.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
652	        if (!periods.close(period, total)) {
653	            throw new InvalidPeriodException("The period " + period.name() + " is already closed");
654	        }
655	        periods.fixPersonTotals(period, perPerson);
656	        closed.set(new PeriodClose(request.by(), total));
657	    }
