1369	/**
1370	 * Takes the person's statement on the sheet's today: their due-total now (the figures of their claims that count
1371	 * added up, each with its late charge; n/a when their grade has no rate today and no counting claim has a
1372	 * figure, kept or at the grade in force on its date; at most the sheet's cap), and binds every claim of theirs that counts (a person's OPEN or PENDING claims dated within a hold of theirs, not bound by a statement, do not, nor do deferred claims) to the figure it has now
1373	 * (never its late charge, which keeps following today); one that does not count is unbound (live again).
1374	 */
1375	public class TakeStatement {
1376	    public void take(@Val Person person, @Val StatementTaker taker, ClaimRepository claims, RateRepository rates,
1377	            SheetRepository sheets, SettingRepository settings, StatementRepository statements, Out<Statement> taken) {
1378	        String sheetId = person.sheetId();
1379	        var today = sheets.today(sheetId);
1380	        LateCharge late = LateCharge.of(sheetId, sheets, settings, claims);
1381	        List<Claim> mine = claims.list(sheetId).stream().filter((c) -> c.personId() == person.id()).toList();
1382	        BigDecimal total = BigDecimal.ZERO.setScale(2);
1383	        boolean figured = false;
1384	        int counted = 0;
1385	        for (Claim c : mine) {
1386	            if (!ClaimDue.countsLive(c, person, today)) {
1387	                claims.bind(c, false, null);
1388	                continue;
1389	            }
1390	            BigDecimal figure = ClaimDue.figure(c, person.gradeOn(c.date()), rates, settings.floor(sheetId, c.date()), late.rounding());
1391	            figured |= figure != null;
1392	            if (figure != null) {
1393	                total = total.add(late.add(c, figure));
1394	            }
1395	            counted++;
1396	            claims.bind(c, true, figure);
1397	        }
1398	        String dueTotal = rates.find(sheetId, person.gradeOn(today), today) == null && !figured ? "n/a" : SettingRepository.capped(total, settings.cap(sheetId)).toPlainString();
1399	        Statement statement = new Statement(sheetId, person.id(), today, dueTotal, counted, taker.by());
1400	        statements.add(statement);
1401	        taken.set(statement);
1402	    }
1403	}
