  number: string | null;
  due: string | null;
  openedBy: string | null;
  stated: boolean;
  statedDue: string | null;
  corrects: string | null;
  roundsOn: string;
  dueBy: string;
  deferred: boolean;
  deferredUntil: string | null;
  log: ClaimLogLine[];
