  return sum(figures);
}

/** A person's due-total: the sum of their figures (see personFigures), at most the sheet's cap (null: none); 'n/a'
 *  is not capped. */
export function personDue(claims: Claim[], rates: Rate[] | undefined, person: Person, late: Late, floor: Dated, cap: string | null): string {
  const total = personFigures(claims, rates, person, late, floor);
  return total !== 'n/a' && cap !== null && hundredths(total) > hundredths(cap) ? shown(hundredths(cap)) : total;
}

/** A person's excess: how far the sum of their figures is above the sheet's cap; 0.00 when it is not (or with no
 *  cap, or an n/a due-total). */
export function personExcess(claims: Claim[], rates: Rate[] | undefined, person: Person, late: Late, floor: Dated, cap: string | null): string {
  const total = personFigures(claims, rates, person, late, floor);
  return total !== 'n/a' && cap !== null && hundredths(total) > hundredths(cap)
    ? shown(hundredths(total) - hundredths(cap))
    : '0.00';
}

/** Two-decimal values added up, skipping 'n/a'. */
export function sum(values: string[]): string {
  return shown(values.filter((v) => v !== 'n/a').reduce((s, v) => s + hundredths(v), 0n));
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { live, type Claim } from '../claims/claims';
import type { Late } from '../overdue/late';
import { gradeOn, type Person } from '../people/people';
import { claimDue, rateFor, sum, type Rate } from '../rates/rates';
import type { Dated } from '../settings/settings';

/** A period of the sheet: `name` is unique on the sheet (case ignored); `from` and `to` (yyyy-MM-dd) are both
 *  inclusive. No two periods of a sheet overlap. A closed period keeps `closedTotal`, the due-total fixed when it
 *  was closed, and `personTotals`, each person's; no claim dated inside it can be added, edited, opened, settled or voided. */
export type Period = {
  id: number;
  sheetId: string;
  name: string;
  from: string;
  to: string;
  closed: boolean;
  closedTotal: string | null;
  /** Closed, each person's due-total for the period fixed when it was closed, by person id. */
  personTotals: Record<string, string>;
};

export const periodsKey = (sheetId: string) => ['sheet', sheetId, 'periods'];

/** The sheet's periods, by from-date. */
export function usePeriods(sheetId: string) {
  return useQuery({
    queryKey: periodsKey(sheetId),
    queryFn: () => getJson<Period[]>(`/api/sheets/${encodeURIComponent(sheetId)}/periods`),
  });
}

/** The period whose dates contain a date (yyyy-MM-dd), or undefined when none does. */
export function periodOf(periods: Period[] | undefined, date: string): Period | undefined {
  return periods?.find((p) => p.from <= date && date <= p.to);
}

/** A person's due-total for a period: the figures of their claims that count, each with its late charge (a
 *  person's OPEN claims dated within a hold of theirs, not bound by a statement, do not), whose date falls in it,
 *  added up (skipping n/a); for a closed period, their figure fixed when it was closed (0.00 for a person added
 *  after). */
export function personPeriodDue(
  period: Period,
  person: Person,
  claims: Claim[] | undefined,
  rates: Rate[] | undefined,
  floor: Dated,
  late: Late,
): string {
  if (period.closed) return period.personTotals?.[String(person.id)] ?? '0.00';
  const mine = live((claims ?? []).filter((c) => c.personId === person.id), [person]).filter(
    (c) => period.from <= c.date && c.date <= period.to,
  );
  return sum(mine.map((c) => claimDue(c, rateFor(rates, gradeOn(person, c.date), c.date), floor, late)));
}

/** A period's due-total: the people's due-totals for it (see personPeriodDue) added up. */
export function periodDue(
  period: Period,
  claims: Claim[] | undefined,
  people: Person[] | undefined,
  rates: Rate[] | undefined,
  floor: Dated,
  late: Late,
): string {
  return sum((people ?? []).map((person) => personPeriodDue(period, person, claims, rates, floor, late)));
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import type { Late } from '../overdue/late';
import { useSheetToday } from '../session/session';

/** A sheet setting: `value` is text (clerk-limit, cap, floor: an amount with two decimals; terms, terms-A, terms-B, terms-C: a whole number of days; late-pct: a percent with two decimals; policy-date, period-numbering-from: yyyy-MM-dd), null when blank.
 *  `from` is the date the value is in force from (yyyy-MM-dd); null when undated (policy-date, period-numbering-from, or a
 *  value from before settings were dated: in force on every date). */
export type Setting = { sheetId: string; key: string; value: string | null; from: string | null };

export const settingsKey = (sheetId: string) => ['sheet', sheetId, 'settings'];

/** The sheet's settings: every value recorded, by key then from-date. */
export function useSettings(sheetId: string) {
  return useQuery({
    queryKey: settingsKey(sheetId),
    queryFn: () => getJson<Setting[]>(`/api/sheets/${encodeURIComponent(sheetId)}/settings`),
  });
}

/** The setting recorded for the key in force on the date (the latest from-date on or before it; an undated one is in
 *  force on every date); undefined when none is. */
export function inForce(settings: Setting[] | undefined, key: string, date: string): Setting | undefined {
  let found: Setting | undefined;
  for (const s of settings ?? []) {
    if (s.key !== key || (s.from !== null && s.from > date)) continue;
    if (found === undefined || (s.from !== null && (found.from === null || s.from > found.from))) found = s;
  }
  return found;
}

/** A dated figure: its value in force on a date (yyyy-MM-dd). */
export type Dated = (date: string) => string;

/** The floor a sheet has until one is set. */
export const DEFAULT_FLOOR = '1.00';

/** The sheet's floor: the least a claim's live due may be (two decimals), the one in force on the claim's date. */
export function useFloor(sheetId: string): Dated {
  const settings = useSettings(sheetId);
  return (date) => inForce(settings.data, 'floor', date)?.value ?? DEFAULT_FLOOR;
}

/** The sheet's cap in force on its today: the most a person's due-total may be (two decimals); null when blank (none). */
export function useCap(sheetId: string): string | null {
  const settings = useSettings(sheetId);
  const today = useSheetToday(sheetId);
  return inForce(settings.data, 'cap', today)?.value ?? null;
}

/** The terms a sheet has until they are set. */
export const DEFAULT_TERMS = '14';


/** The late percent a sheet has until one is set. */
export const DEFAULT_LATE_PCT = '0.00';

/** What the sheet's late charge depends on: its today, its late percent (the one in force on a claim's date) and its
 *  policy date (its today while blank), which decides how claims round. */
export function useLate(sheetId: string): Late {
  const settings = useSettings(sheetId);
  const today = useSheetToday(sheetId);
  const policy = settings.data?.find((s) => s.key === 'policy-date')?.value ?? today;
  return { today, pct: (date) => inForce(settings.data, 'late-pct', date)?.value ?? DEFAULT_LATE_PCT, policy };
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A person's statements: how many were taken, and the last one's due-total (two decimals, or n/a) and date
 *  (yyyy-MM-dd, the sheet's today when it was taken). A person with none has no entry. */
export type StatementSummary = { personId: number; count: number; dueTotal: string; date: string };

export const statementsKey = (sheetId: string) => ['sheet', sheetId, 'statements'];

/** Each person's statements on the sheet. */
export function useStatements(sheetId: string) {
  return useQuery({
    queryKey: statementsKey(sheetId),
    queryFn: () => getJson<StatementSummary[]>(`/api/sheets/${encodeURIComponent(sheetId)}/statements`),
  });
}
import { useSearchParam } from '../../url/useSearchParam';

/** The selected claims' ids, kept in the URL (`selected`, comma-separated) so a bulk action reads them. */
export function useSelectedClaims(): [number[], (ids: number[]) => void] {
  const [raw, setRaw] = useSearchParam('selected', (r) => (typeof r === 'string' || typeof r === 'number' ? String(r) : ''));
  const ids = raw
    .split(',')
    .filter((s) => s !== '')
    .map(Number)
    .filter((n) => !Number.isNaN(n));
  return [ids, (next) => setRaw(next.length === 0 ? undefined : next.join(','))];
}

