      postJson<Result>(`/api/sheets/${encodeURIComponent(sheetId)}/bulk-settle`, { claimIds, by: user }),
    onSuccess: async () => {
      setSelected([]);
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
  });
  return (
    <p>
      <button
        type="button"
        data-testid="bulk-settle"
        disabled={settle.isPending}
        onClick={() => {
          settle.reset();
          settle.mutate(selected);
        }}
      >
        Settle selected ({selected.length})
      </button>
      {settle.isSuccess && (
        <>
          {' '}
          Settled <span data-testid="bulk-settled">{settle.data.settled}</span>, refused{' '}
          <span data-testid="bulk-settle-refused">{settle.data.refused}</span>
        </>
      )}
      {settle.isError && <span data-testid="bulk-settle-error"> Could not settle the selected claims.</span>}
    </p>
  );
}
export const contribution = SheetPage.fill({ order: 26, Component: BulkSettle });
type Result = { opened: number; refused: number };
/** Opens the selected claims together: each that can be opened is opened and numbered in list order (people in
 *  order, a person's claims newest first); each that cannot is left as it is. Shows how many were opened and how
 *  many refused; the counts are cleared while a new press runs. */
function BulkOpen({ sheetId, user }: { sheetId: string; user: string }) {
  const queryClient = useQueryClient();
  const [selected, setSelected] = useSelectedClaims();
  const open = useMutation({
    mutationFn: (claimIds: number[]) =>
      postJson<Result>(`/api/sheets/${encodeURIComponent(sheetId)}/bulk-open`, { claimIds, by: user }),
    onSuccess: async () => {
      setSelected([]);
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
  });
  return (
    <p>
      <button
        type="button"
        data-testid="bulk-open"
        disabled={open.isPending}
        onClick={() => {
          open.reset();
          open.mutate(selected);
        }}
      >
        Open selected ({selected.length})
      </button>
      {open.isSuccess && (
        <>
          {' '}
          Opened <span data-testid="bulk-opened">{open.data.opened}</span>, refused{' '}
          <span data-testid="bulk-refused">{open.data.refused}</span>
        </>
      )}
      {open.isError && <span data-testid="bulk-open-error"> Could not open the selected claims.</span>}
    </p>
  );
}
export const contribution = SheetPage.fill({ order: 25, Component: BulkOpen });
type Result = { added: number };
/** The paste box: lines of name,amount,date,note (the note may hold commas and may be absent; a blank date is the
 *  sheet's today) each add a DRAFT claim, in order, for the person with the name. The server checks every line by the
 *  claim form's rules first: one failing line refuses the paste and adds nothing. Shows how many were added; the
 *  count is cleared while a new press runs. */
function PasteClaims({ sheetId, user }: { sheetId: string; user: string }) {
  const queryClient = useQueryClient();
  const [text, setText] = useState('');
  const submit = useSubmitOnce();
  const paste = useMutation({
    mutationFn: (t: string) =>
      postJson<Result>(`/api/sheets/${encodeURIComponent(sheetId)}/paste-claims`, { text: t, by: user }),
    onSuccess: () => {
      setText('');
      void queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
      void queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
    onSettled: submit.end,
  });
  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        if (!submit.begin()) return;
        paste.reset();
        paste.mutate(text);
      }}
    >
      <label>
        Paste claims (name,amount,date,note per line)
        <br />
        <textarea
          data-testid="paste-claims"
          rows={4}
          cols={50}
          value={text}
          onChange={(e) => {
            setText(e.target.value);
            paste.reset();
          }}
        />
      </label>
      <br />
      <button type="submit" data-testid="paste-submit" disabled={paste.isPending}>
        Add draft claims
      </button>
      {paste.isSuccess && (
        <>
          {' '}
          Added <span data-testid="paste-added">{paste.data.added}</span>
        </>
      )}
      {paste.isError && (
        <span data-testid="paste-error">
          {' '}
          Nothing was added: every line must name a person on the sheet and keep the claim form's rules.
        </span>
      )}
    </form>
  );
}
export const contribution = SheetPage.fill({ order: 24, Component: PasteClaims });
// Who is signed in and which sheet is active live in the URL (`user`, `sheet`), so any feature
// reads them directly. There is no password: signing in is typing a name.
export const useUser = () => useSearchParam('user', asString);
export const useSheetId = () => useSearchParam('sheet', asString);
/** `today` (yyyy-MM-dd) is the sheet's own date: every date decision and default date on the
 *  sheet uses it, never the browser's clock. */
export type Sheet = { id: string; today: string };
/** The active sheet as the store holds it. Keyed ['sheet', id]: every per-sheet key starts so. */
export function useSheet(sheetId: string) {
  return useQuery({
    queryKey: ['sheet', sheetId],
    queryFn: () => getJson<Sheet>(`/api/sheets/${encodeURIComponent(sheetId)}`),
    enabled: sheetId !== '',
  });
}
/** The sheet's today (yyyy-MM-dd), or '' while the sheet loads. Use it for every default date. */
export function useSheetToday(sheetId: string): string {
  return useSheet(sheetId).data?.today ?? '';
}

